1	import fs from "node:fs";
2	import path from "node:path";
3	import { readJson, outputDir, sanitizeText, toProjectPath, videoRunFiles, writeJson, type StoryboardFile } from "./video-workflow-shared";
4	
5	type TaskStatus = "pending" | "processing" | "completed" | "failed" | "cancelled";
6	type JsonRecord = Record<string, unknown>;
7	
8	const homeDir = process.env.HOME ?? "";
9	const configuredFallbacks = (process.env.REAL_MEDIA_ENV_FALLBACKS ?? "")
10	  .split(path.delimiter)
11	  .map((item) => item.trim())
12	  .filter(Boolean);
13	
14	const envCandidates = [
15	  path.resolve(process.cwd(), ".env.local"),
16	  process.env.REAL_MEDIA_ENV_FILE ? path.resolve(process.env.REAL_MEDIA_ENV_FILE) : null,
17	  ...configuredFallbacks.map((item) => path.resolve(item)),
18	  homeDir ? path.join(homeDir, "Desktop", "tt_idea", "ttvideo_workflow", ".env") : null,
19	  homeDir ? path.join(homeDir, "Desktop", "ship", "youtube_long", ".env") : null,
20	  homeDir ? path.join(homeDir, "Desktop", "ship", "oldmoney_main", ".env") : null
21	].filter(Boolean) as string[];
22	
23	function loadEnvFile(filePath: string) {
24	  if (!fs.existsSync(filePath)) return false;
25	  const lines = fs.readFileSync(filePath, "utf8").split(/\r?\n/);
26	  for (const line of lines) {
27	    const trimmed = line.trim();
28	    if (!trimmed || trimmed.startsWith("#")) continue;
29	    const eqIndex = trimmed.indexOf("=");
30	    if (eqIndex === -1) continue;
31	    const key = trimmed.slice(0, eqIndex).trim();
32	    const rawValue = trimmed.slice(eqIndex + 1).trim();
