1	import fs from "node:fs";
2	import path from "node:path";
3	import { existsProjectPath, readJson, videoRunFiles, writeJson, type StoryboardFile } from "./video-workflow-shared";
4	
5	interface CheckItem {
6	  name: string;
7	  ok: boolean;
8	  detail: string;
9	}
10	
11	function item(name: string, ok: boolean, detail: string): CheckItem {
12	  return { name, ok, detail };
13	}
14	
15	function sum(values: number[]) {
16	  return values.reduce((total, value) => total + value, 0);
17	}
18	
19	function near(left: number, right: number, tolerance = 0.75) {
20	  return Math.abs(left - right) <= tolerance;
21	}
22	
23	function normalizeSubtitleText(value: string) {
24	  return value.replace(/\s+/g, "");
25	}
26	
27	function parseSrtTime(value: string) {
28	  const match = value.match(/^(\d{2}):(\d{2}):(\d{2}),(\d{3})$/);
29	  if (!match) return null;
30	  const [, hours, minutes, seconds, ms] = match;
31	  return Number(hours) * 3600 + Number(minutes) * 60 + Number(seconds) + Number(ms) / 1000;
32	}
33	
34	function parseSrt(text: string) {
35	  const blocks = text.trim().split(/\r?\n\r?\n+/).filter(Boolean);
36	  return blocks.flatMap((block) => {
37	    const lines = block.split(/\r?\n/);
38	    const timingIndex = lines.findIndex((line) => line.includes("-->"));
39	    if (timingIndex === -1) return [];
40	    const [startRaw, endRaw] = lines[timingIndex].split("-->").map((item) => item.trim());
41	    const start = parseSrtTime(startRaw);
42	    const end = parseSrtTime(endRaw);
43	    if (start === null || end === null) return [];
44	    return [{ start, end, text: lines.slice(timingIndex + 1).join("") }];
45	  });
46	}
47	
48	type AudioMode = "real_tts_completed" | "mock_fallback";
49	
50	interface RealAudioManifest {
51	  ok?: boolean;
52	  provider?: string;
53	  media_type?: string;
54	  mode?: AudioMode;
55	  retry_policy?: { hard_cap?: number };
56	  timeline?: {
57	    aligned_to_audio_duration?: boolean;
58	    total_duration_seconds?: number;
59	    items?: Array<{ order?: number; start_seconds?: number; duration_seconds?: number; audio_path?: string }>;
60	  };
61	  audio?: Array<{ order?: number; status?: AudioMode; path?: string; duration_seconds?: number }>;
62	}
63	
64	interface FinalVideoManifest {
65	  final_video?: { path?: string; duration_seconds?: number };
66	  real_provider_images?: string[];
67	  uses_provider_video?: boolean;
68	  storyboard_items?: number;
69	  audio_timeline?: Array<{ order?: number; start_seconds?: number; duration_seconds?: number; audio_path?: string }>;
70	  subtitle_assets?: {
71	    srt_path?: string;
72	    aligned_to_audio_timeline?: boolean;
73	    burned_in?: boolean;
74	    render_method?: string;
75	    image_paths?: string[];
76	    cue_count?: number;
77	  };
78	}
79	
80	interface MediaManifest {
81	  media_tasks?: Array<{ media_id?: string; task_status?: string }>;
82	  failure_recovery?: {
83	    media_id?: string;
84	    forced_failure?: boolean;
85	    auto_retry?: boolean;
86	    requires_model_action?: boolean;
87	    retried?: boolean;
88	    final_status?: string;
89	  };
90	}
91	
92	const checks: CheckItem[] = [];
93	
94	for (const required of [
95	  videoRunFiles.request,
96	  videoRunFiles.researchNotes,
97	  videoRunFiles.storyboard,
98	  videoRunFiles.mediaPlan,
99	  videoRunFiles.taskRun,
100	  videoRunFiles.mediaManifest,
101	  videoRunFiles.subagentReview
102	]) {
103	  checks.push(item(`required:${required}`, existsProjectPath(required), existsProjectPath(required) ? "exists" : "missing"));
104	}
105	
106	let storyboard: StoryboardFile | null = null;
107	try {
108	  storyboard = readJson<StoryboardFile>(videoRunFiles.storyboard);
109	  checks.push(item("storyboard:parse", true, "valid json"));
110	} catch (error) {
111	  checks.push(item("storyboard:parse", false, error instanceof Error ? error.message : String(error)));
112	}
113	
114	if (storyboard) {
115	  checks.push(item("storyboard:theme", storyboard.theme === "快来购买豆包高级套餐吧！", storyboard.theme));
116	  checks.push(item("storyboard:item_count", storyboard.items.length === 3, String(storyboard.items.length)));
117	  checks.push(item("storyboard:duration", storyboard.total_duration_seconds >= 28 && storyboard.total_duration_seconds <= 34, String(storyboard.total_duration_seconds)));
118	  for (const storyboardItem of storyboard.items) {
119	    checks.push(item(`storyboard:image:${storyboardItem.order}`, existsProjectPath(storyboardItem.image_asset), storyboardItem.image_asset));
120	    checks.push(item(`storyboard:audio:${storyboardItem.order}`, existsProjectPath(storyboardItem.audio_manifest_path), storyboardItem.audio_manifest_path));
121	  }
122	}
123	
124	if (existsProjectPath(videoRunFiles.mediaManifest)) {
125	  try {
