1	import { pollMockProviderTask, submitMockAudioTask, submitMockProviderTask } from "./mock-provider";
2	import { addAudioTask, addTask, getMediaCard, getSegment, listAudioTasks, listTasks, updateAudioTask, updateMediaCard, updateTask } from "./mock-store";
3	import type { MediaTask, SegmentAudioTask, SegmentMedia } from "./types";
4	
5	function now() {
6	  return new Date().toISOString();
7	}
8	
9	function nextTaskId(media_id: string, index: number) {
10	  return `${media_id}_TASK_${String(index).padStart(2, "0")}`;
11	}
12	
13	function nextAudioTaskId(segment_id: string, index: number) {
14	  return `${segment_id}_AUDIO_TASK_${String(index).padStart(2, "0")}`;
15	}
16	
17	export function recalculateMediaStatus(media_id: string) {
18	  const tasks = listTasks(media_id);
19	  if (tasks.length === 0) {
20	    return updateMediaCard(media_id, {
21	      aggregate_status: "idle",
22	      preview_url: null,
23	      last_error: null
24	    });
25	  }
26	
27	  const failed = tasks.find((task) => task.task_status === "failed");
28	  if (failed) {
29	    return updateMediaCard(media_id, {
30	      aggregate_status: "failed",
31	      preview_url: null,
32	      last_error: failed.error_message ?? "Mock provider task failed."
33	    });
34	  }
35	
36	  if (tasks.some((task) => task.task_status === "pending" || task.task_status === "processing")) {
37	    return updateMediaCard(media_id, {
38	      aggregate_status: "processing",
39	      last_error: null
40	    });
41	  }
42	
43	  const completed = tasks.find((task) => task.task_status === "completed" && task.result_url);
44	  return updateMediaCard(media_id, {
45	    aggregate_status: "completed",
46	    preview_url: completed?.result_url ?? null,
47	    last_error: null
48	  });
49	}
50	
51	export function submitMedia(media_id: string) {
52	  const media = getMediaCard(media_id);
53	  if (!media) throw new Error(`Media card not found: ${media_id}`);
54	
55	  if (media.aggregate_status === "processing" || media.aggregate_status === "completed") {
56	    return {
57	      media,
58	      tasks: listTasks(media_id),
59	      created: false,
60	      message: `media ${media_id} is already ${media.aggregate_status}`
61	    };
62	  }
63	
64	  if (media.aggregate_status === "failed") {
65	    return {
66	      media,
67	      tasks: listTasks(media_id),
68	      created: false,
69	      message: `media ${media_id} is failed; retry explicitly`
70	    };
71	  }
72	
73	  const existing = listTasks(media_id);
74	  if (existing.length > 0) {
75	    return {
76	      media,
77	      tasks: existing,
78	      created: false,
79	      message: `media ${media_id} already has tasks`
80	    };
81	  }
82	
83	  const created: MediaTask[] = [];
84	  for (let index = 1; index <= media.generate_count; index += 1) {
85	    const provider_task_id = submitMockProviderTask(media);
86	    created.push(
87	      addTask({
88	        media_task_id: nextTaskId(media_id, index),
89	        media_id,
90	        task_index: index,
91	        provider_task_id,
92	        task_status: "processing",
93	        result_url: null,
94	        error_message: null,
95	        created_at: now(),
96	        updated_at: now()
97	      })
98	    );
99	  }
100	
101	  const updated = recalculateMediaStatus(media_id);
102	  updateMediaCard(media_id, {
103	    last_submitted_at: now()
104	  });
105	
106	  return {
107	    media: updated,
108	    tasks: created,
109	    created: true,
110	    message: `media ${media_id} submitted`
111	  };
112	}
113	
114	export function pollRunningTasks(limit = 50) {
115	  const running = listTasks().filter((task) => task.task_status === "pending" || task.task_status === "processing").slice(0, limit);
116	  const touched = new Set<string>();
117	  const updatedTasks: MediaTask[] = [];
118	
119	  for (const task of running) {
120	    const result = pollMockProviderTask(task.provider_task_id);
121	    const updated = updateTask(task.media_task_id, {
122	      task_status: result.task_status,
123	      result_url: result.result_url,
124	      error_message: result.error_message
125	    });
126	    touched.add(task.media_id);
127	    updatedTasks.push(updated);
128	  }
129	
130	  for (const media_id of touched) recalculateMediaStatus(media_id);
131	
132	  const remainingLimit = Math.max(0, limit - updatedTasks.length);
133	  const runningAudio = listAudioTasks()
134	    .filter((task) => task.task_status === "pending" || task.task_status === "processing")
135	    .slice(0, remainingLimit);
136	  const updatedAudioTasks: SegmentAudioTask[] = [];
137	
138	  for (const task of runningAudio) {
139	    const result = pollMockProviderTask(task.provider_task_id);
140	    updatedAudioTasks.push(
141	      updateAudioTask(task.audio_task_id, {
142	        task_status: result.task_status,
143	        result_url: result.result_url,
144	        error_message: result.error_message
145	      })
146	    );
147	  }
148	
149	  return {
150	    updated_tasks: updatedTasks.length + updatedAudioTasks.length,
151	    tasks: updatedTasks,
152	    audio_tasks: updatedAudioTasks
153	  };
154	}
155	
156	export function submitSegmentAudio(segment_id: string, source_text?: string) {
157	  const segment = getSegment(segment_id);
158	  if (!segment) throw new Error(`Segment not found: ${segment_id}`);
159	
160	  const text = (source_text ?? segment.narration_cn ?? segment.narration ?? "").trim();
161	  if (!text) throw new Error("Audio source text is empty");
162	
163	  const existing = listAudioTasks(segment_id);
164	  const latest = existing.at(-1);
165	  if (latest?.task_status === "processing" || latest?.task_status === "pending" || latest?.task_status === "completed") {
166	    return {
167	      task: latest,
168	      created: false,
169	      message: `audio for ${segment_id} is already ${latest.task_status}`
170	    };
171	  }
172	
173	  if (latest?.task_status === "failed") {
174	    return {
175	      task: latest,
176	      created: false,
177	      message: `audio for ${segment_id} is failed; retry explicitly`
178	    };
179	  }
180	
181	  const provider_task_id = submitMockAudioTask(segment_id, text);
182	  const task = addAudioTask({
183	    audio_task_id: nextAudioTaskId(segment_id, existing.length + 1),
184	    segment_id,
185	    provider_task_id,
186	    task_status: "processing",
187	    source_text: text,
188	    result_url: null,
189	    error_message: null,
190	    created_at: now(),
191	    updated_at: now()
192	  });
193	
194	  return {
195	    task,
196	    created: true,
197	    message: `audio for ${segment_id} submitted`
198	  };
199	}
200	
201	export function retrySegmentAudio(segment_id: string, source_text?: string) {
202	  const segment = getSegment(segment_id);
203	  if (!segment) throw new Error(`Segment not found: ${segment_id}`);
204	  const failed = [...listAudioTasks(segment_id)].reverse().find((task) => task.task_status === "failed");
205	  if (!failed) {
206	    return {
207	      task: listAudioTasks(segment_id).at(-1) ?? null,
208	      retried: false,
209	      message: `audio for ${segment_id} is not failed`
210	    };
211	  }
212	
213	  const text = (source_text ?? failed.source_text ?? segment.narration_cn ?? segment.narration ?? "").replace(/\s*\[FAIL\]/g, "").trim();
214	  if (!text) throw new Error("Audio source text is empty");
215	
216	  const provider_task_id = submitMockAudioTask(segment_id, text);
217	  const task = updateAudioTask(failed.audio_task_id, {
218	    provider_task_id,
219	    task_status: "processing",
